const { title, body, head, base, draft } = $.input;
if (!title) throw new Error('title is required');
if (!head) throw new Error('head branch is required');

const payload = {
  title,
  head,
  base: base || 'main'
};
if (body) payload.body = body;
if (draft) payload.draft = true;

return { payload };
